        if (IS_THING_ALIVE<CThing*>(hero)) {
            CGameEvent event(GAME_EVENT_OPEN_INVENTORY);
            event.Player = hero->PlayerNumber;
            event.AddLong(4);
            g_pMainGameComponent->AddGameEvent(event);
        }
        OpenInventory = false;
    }
